use std::rc::Rc;
use std::thread;

// ❌ OLD: Rc<T> is !Send (and !Sync): its reference count is a plain
// field, not atomic, so moving it to another thread would let two
// threads race on the refcount — a data race. The compiler REJECTS
// this at compile time:
fn main() {
    let rc = Rc::new(5);
    // error[E0277]: `Rc<i32>` cannot be sent between threads safely
    let h = thread::spawn(move || {
        let _ = *rc;
    });
    h.join().unwrap();
}

// This is the point: the failure is a COMPILE error, caught before
// the program ever runs, instead of a runtime data race.

use std::sync::Arc;
use std::thread;

// ✅ NEW: Arc<T> uses an ATOMIC reference count, so it is Send + Sync
// (when T: Send + Sync). Moving clones into threads is safe and
// compiles.
fn main() {
    let arc = Arc::new(5); // ✅ NEW: thread-safe shared ownership
    let h = thread::spawn(move || {
        let _ = *arc; // ✅ NEW: safe read
    });
    h.join().unwrap();
}

